mapper.update:
UPDATE borrow_record
SET status = #{status},
    update_time = CURRENT_TIMESTAMP
WHERE status = #{oldStatus}
  AND due_time < #{now}
  AND return_time IS NULL

mapper.select:
SELECT COUNT(1)
FROM borrow_record
WHERE reader_id = #{readerId}
  AND book_id = #{bookId}
  AND status IN ('BORROWED', 'OVERDUE')

SELECT COUNT(1)
FROM borrow_record
WHERE reader_id = #{readerId}

    AND status = #{status}

SELECT br.id, br.book_id, br.reader_id, br.borrow_time, br.due_time, br.return_time, br.status, br.create_time, br.update_time, b.title AS book_title, b.isbn AS book_isbn, r.name AS reader_name FROM borrow_record br LEFT JOIN book b ON br.book_id = b.id LEFT JOIN reader r ON br.reader_id = r.id WHERE br.reader_id = #{readerId}
AND br.status = #{status}
ORDER BY br.id DESC LIMIT #{offset}, #{pageSize}
